"""R12: longitud, masa, capacidad y tiempo. Ejercicios originales y cantidades exactas."""
import json
from decimal import Decimal as D
from pathlib import Path
U=[]
def fmt(x):
 s=format(D(x),'f');return (s.rstrip('0').rstrip('.') if '.' in s else s).replace('.',',')
def a(q,answer,steps,wrong):
 opts=list(dict.fromkeys([str(answer),*map(str,wrong)]));assert len(opts)>1
 return dict(enunciado=q,respuesta_correcta=str(answer),opciones=opts,paso_resuelto=steps,visual=None)
def unit(id,t,after,title,explanation,example,steps,hint,rows):
 assert len(rows)==6
 for i,row in enumerate(rows):
  row['id']=id+'-v'+str(i+1);k=i%len(row['opciones']);row['opciones']=row['opciones'][k:]+row['opciones'][:k]
 U.append(dict(id=id,tema=t,despues_de=after,titulo=title,explicacion=explanation,ejemplo=example,pasos=steps,pista=hint,visual=None,actividades=rows))
def conversion(qty,src,dst,factor):
 value=D(qty)*D(factor);op='×' if D(factor)>=1 else '÷';number=D(factor) if D(factor)>=1 else 1/D(factor)
 relation=f'1 {src} = {fmt(factor)} {dst}' if D(factor)>=1 else f'1 {dst} = {fmt(number)} {src}'
 return a(f'Convertí {fmt(qty)} {src} a {dst}. ¿Qué número va delante de {dst}?',fmt(value),f'{relation}.\n{fmt(qty)} {op} {fmt(number)} = {fmt(value)}. Son {fmt(value)} {dst}; la cantidad medida es la misma.',[fmt(D(qty)/D(factor)),fmt(value+1)])
t='si_me_la_longitud'
unit('prof_med_long_escala',t,'mat_long_metros','Una escala para medir longitudes','Ordenamos las unidades de mayor a menor: km → hm → dam → m → dm → cm → mm. Se llaman kilómetro, hectómetro, decámetro, metro, decímetro, centímetro y milímetro. Cada unidad contiene diez de la siguiente: al usar una unidad menor necesitamos más partes para la misma longitud.','3 m = 30 dm: de m a dm hay un paso hacia una unidad menor.',['Un metro contiene diez decímetros.','Tres metros contienen 3 × 10 = 30 decímetros.'],'La medida no cambia: cambia cuántas partes de esa unidad contamos.',[conversion(n,src,dst,10) for n,src,dst in [(3,'m','dm'),(2,'km','hm'),(4,'hm','dam'),(5,'dam','m'),(6,'dm','cm'),(7,'cm','mm')]])
unit('prof_med_long_menor',t,'prof_med_long_escala','Contar varios pasos hacia unidades menores','Cada paso hacia una unidad menor multiplica el número por diez. Dos pasos multiplican por 100 y tres por 1000. Contamos los saltos entre unidades, no la cantidad de nombres escritos.','2 m = 2000 mm.',['De m a mm recorremos m → dm → cm → mm: tres saltos.','2 × 10 × 10 × 10 = 2000 mm.'],'Marcá la unidad inicial y la final; contá los saltos.',[conversion(n,src,dst,k) for n,src,dst,k in [(2,'m','mm',1000),(3,'km','m',1000),(4,'hm','m',100),(5,'dam','cm',1000),(6,'dm','mm',100),(7,'m','cm',100)]])
unit('prof_med_long_mayor',t,'prof_med_long_menor','Agrupar en unidades mayores','Para pasar a una unidad mayor agrupamos partes pequeñas. De centímetros a metros agrupamos de cien: dividimos por 100. Cada salto hacia una unidad mayor divide por diez. La cantidad escrita disminuye y la longitud se conserva.','300 cm = 3 m.',['Cada metro reúne 100 centímetros.','300 ÷ 100 = 3 grupos: son 3 metros.'],'Hacia una unidad mayor, dividí por diez en cada salto.',[conversion(n,src,dst,k) for n,src,dst,k in [(300,'cm','m','.01'),(4000,'m','km','.001'),(50,'mm','cm','.1'),(600,'dm','dam','.01'),(7000,'mm','m','.001'),(800,'m','hm','.01')]])
unit('prof_med_long_decimal',t,'prof_med_long_mayor','Cuando la medida incluye parte de una unidad','Un decimal puede expresar una parte de una medida. En 1,25 m hay un metro y 25 centésimos de metro. Como un metro tiene 100 centímetros, esos 25 centésimos son 25 cm. Para convertir usamos la misma equivalencia aunque el número tenga coma.','1,25 m = 125 cm; 75 cm = 0,75 m.',['1 m aporta 100 cm y 0,25 m aporta 25 cm: 100 + 25 = 125 cm.','75 cm son 75 de las 100 partes de un metro: 75 ÷ 100 = 0,75 m.'],'Pensá cuánto vale un entero en la unidad de destino.',[conversion(n,src,dst,k) for n,src,dst,k in [('1.25','m','cm',100),('2.5','km','m',1000),('0.4','m','mm',1000),(75,'cm','m','.01'),(1500,'m','km','.001'),(35,'mm','cm','.1')]])
unit('prof_med_long_problema',t,'mat_long_combinar','Convertir primero, cortar después','Para saber cuánto queda de una cinta, expresamos la cinta y el corte en la misma unidad antes de restar. Elegimos una unidad que permita hacer la cuenta y escribimos la unidad del resultado.','Una cinta de 2 m pierde un trozo de 35 cm. Quedan 165 cm.',['Pasamos la cinta a centímetros: 2 × 100 = 200 cm.','Restamos el corte: 200 − 35 = 165 cm.'],'Primero igualá las unidades; después restá el corte.',[a(f'Una cinta mide {fmt(n)} m. Cortás {c} cm. ¿Cuántos centímetros quedan?',fmt(D(n)*100-c),f'{fmt(n)} m = {fmt(D(n)*100)} cm.\n{fmt(D(n)*100)} − {c} = {fmt(D(n)*100-c)} cm.',[fmt(D(n)*100+c),fmt(D(n)*100)]) for n,c in [('2',35),('1.5',40),('3',75),('2.25',50),('1.2',35),('4',125)]])
t='si_me_la_masa_capacidad_tiempo'
unit('prof_med_masa_escala',t,'mat_med_masa_capacidad','La escala de la masa','Las unidades de masa forman esta escala: kg → hg → dag → g → dg → cg → mg. Son kilogramo, hectogramo, decagramo, gramo, decigramo, centigramo y miligramo. Cada paso hacia una unidad menor multiplica por diez; hacia una mayor divide por diez.','2 kg = 200 dag.',['De kg a dag hay dos pasos: kg → hg → dag.','2 × 100 = 200 dag; seguimos midiendo la misma masa.'],'Usá solo unidades de masa y contá los saltos de su escala.',[conversion(n,src,dst,k) for n,src,dst,k in [(2,'kg','dag',100),(3,'hg','g',100),(4,'g','mg',1000),(5000,'mg','g','.001'),(600,'cg','g','.01'),(700,'dag','kg','.01')]])
unit('prof_med_cap_escala',t,'prof_med_masa_escala','La escala de la capacidad','Para medir capacidad usamos kL → hL → daL → L → dL → cL → mL: kilolitro, hectolitro, decalitro, litro, decilitro, centilitro y mililitro. Cada salto cambia el número por un factor diez. Los litros miden capacidad; los gramos miden masa. No los intercambiamos.','3 L = 300 cL.',['De L a cL hay dos pasos: L → dL → cL.','3 × 100 = 300 cL. Es la misma capacidad.'],'Conservá la magnitud: una capacidad se convierte a otra unidad de capacidad.',[conversion(n,src,dst,k) for n,src,dst,k in [(3,'L','cL',100),(2,'kL','L',1000),(4,'hL','L',100),(5000,'mL','L','.001'),(600,'cL','L','.01'),(700,'dL','daL','.01')]])
unit('prof_med_masa_decimal',t,'prof_med_cap_escala','Partes de un kilogramo','Un kilogramo tiene 1000 gramos. Medio kilogramo, escrito 0,5 kg, contiene 500 g. Para pasar de kg a g multiplicamos por 1000; para volver dividimos por 1000. La coma puede indicar una parte de kilogramo, no una masa diferente.','1,25 kg = 1250 g; 750 g = 0,75 kg.',['1 kg aporta 1000 g y un cuarto de kg, 0,25 kg, aporta 250 g: suman 1250 g.','750 g son 750 de las 1000 partes de un kg: 750 ÷ 1000 = 0,75 kg.'],'Un kilogramo contiene mil gramos; usá esa equivalencia en ambos sentidos.',[conversion(n,src,dst,k) for n,src,dst,k in [('1.25','kg','g',1000),('0.5','kg','g',1000),('2.4','kg','g',1000),(750,'g','kg','.001'),(1500,'g','kg','.001'),(250,'g','kg','.001')]])
unit('prof_med_masa_problema',t,'prof_med_masa_decimal','Cuánto queda en la bolsa','Para calcular cuánto queda de un material, pasamos todas las masas a gramos y luego restamos. El número del paquete puede estar en kilogramos y el de una porción en gramos: primero los hacemos comparables.','Una bolsa tiene 1,5 kg de harina. Si usamos 250 g, quedan 1250 g.',['1,5 × 1000 = 1500 g.','1500 − 250 = 1250 g.'],'Convertí la masa inicial a gramos antes de quitar lo usado.',[a(f'Una bolsa contiene {fmt(n)} kg de harina. Usás {g} g. ¿Cuántos gramos quedan?',fmt(D(n)*1000-g),f'{fmt(n)} × 1000 = {fmt(D(n)*1000)} g.\n{fmt(D(n)*1000)} − {g} = {fmt(D(n)*1000-g)} g.',[fmt(D(n)*1000+g),fmt(D(n)*1000)]) for n,g in [('1.5',250),('2',750),('0.75',200),('1.25',450),('3',1250),('2.5',800)]])
unit('prof_med_cap_problema',t,'prof_med_masa_problema','Repartir una bebida en vasos','Un litro contiene 1000 mL y medio litro, 0,5 L, contiene 500 mL. Para saber cuántos vasos podemos llenar, convertimos la bebida a mililitros y dividimos entre la capacidad de un vaso. Contamos vasos completos; en estos ejemplos no sobra bebida.','1,5 L de jugo llenan 6 vasos de 250 mL.',['1,5 L = 1000 mL + 500 mL = 1500 mL.','1500 ÷ 250 = 6. Comprobamos: 6 × 250 = 1500 mL.'],'Primero pasá todo a mL; después buscá cuántas veces entra un vaso.',[a(f'Tenés {fmt(n)} L de jugo y vasos de {ml} mL. ¿Cuántos vasos completos llenás sin que sobre?',fmt(D(n)*1000/ml),f'{fmt(n)} L = {fmt(D(n)*1000)} mL.\n{fmt(D(n)*1000)} ÷ {ml} = {fmt(D(n)*1000/ml)} vasos. Comprobación: {fmt(D(n)*1000/ml)} × {ml} = {fmt(D(n)*1000)} mL.',[fmt(D(n)*1000/ml+1),fmt(D(n)*1000/ml-1)]) for n,ml in [('1.5',250),('2',200),('0.75',250),('1.2',200),('2.5',500),('3',250)]])
unit('prof_med_tiempo_resto',t,'mat_med_tiempo','Agrupar minutos en horas','Para escribir minutos como horas y minutos, agrupamos de sesenta. El cociente indica las horas completas y el resto, los minutos que todavía no forman otra hora. No escribimos 90 minutos como 0,90 horas.','95 minutos son 1 h y 35 min.',['95 ÷ 60 da 1 hora completa y sobran 35 minutos.','Comprobamos: 1 × 60 + 35 = 95 minutos.'],'Cada hora completa reúne 60 minutos; conservá lo que sobra.',[a(f'Expresá {n} minutos como horas y minutos.',f'{n//60} h {n%60} min',f'{n} ÷ 60: {n//60} hora(s) y resto {n%60} minutos.\n{n//60} × 60 + {n%60} = {n}.',[f'{n//100} h {n%100} min',f'{n//60} h {n%60+1} min']) for n in [95,130,75,145,185,250]])
unit('prof_med_tiempo_duracion',t,'prof_med_tiempo_resto','Cuánto dura una actividad','Para hallar una duración dentro del mismo día, podemos avanzar desde la hora de inicio hasta la siguiente hora y después hasta el final. Sumamos los dos tramos en minutos. Esta cuenta usa 60 minutos por hora.','Una actividad de 14:40 a 15:15 dura 35 minutos.',['De 14:40 a 15:00 pasan 60 − 40 = 20 minutos.','De 15:00 a 15:15 pasan 15 minutos: 20 + 15 = 35 minutos.'],'Partí el recorrido en la hora en punto y sumá los minutos.',[a(f'Una actividad empieza a las {h:02d}:{m:02d} y termina a las {h+1:02d}:{end:02d} del mismo día. ¿Cuántos minutos dura?',60-m+end,f'Hasta las {h+1:02d}:00: 60 − {m} = {60-m} minutos.\nDespués pasan {end} minutos más: {60-m} + {end} = {60-m+end} minutos.',[100-m+end,60-m+end+10]) for h,m,end in [(14,40,15),(9,50,20),(16,35,10),(11,45,5),(18,20,25),(8,55,15)]])
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8')
start='// R12: medidas paso a paso.';end='// FIN R12'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst MEDIDAS_R12 = '+json.dumps(U,ensure_ascii=False,indent=2)+''';
for (const unidad of MEDIDAS_R12) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === unidad.despues_de);
 if (indice < 0) throw new Error('Falta el paso anterior de ' + unidad.id);
 UNIDADES_BASES.splice(indice + 1, 0, unidad);
}
'''+end+'\n\n'
i=s.index('// R13: geometria con diagramas.') if '// R13: geometria con diagramas.' in s else min(s.index(m) for m in ['// R14: figuras y superficies.','export const TEMAS_BASES'] if m in s);p.write_text(s[:i]+code+s[i:],encoding='utf-8')
print(len(U),'unidades nuevas;',sum(len(u['actividades']) for u in U),'actividades')
